// Define URLs to scrape
const urls = [
  'https://rhythmtraffic.com',
  'https://rhythmtraffic.com/about',
  'https://rhythmtraffic.com/services',
  'https://rhythmtraffic.com/solutions',
  'https://rhythmtraffic.com/contact',
  // Add more URLs as needed
];

return urls.map(url => ({ json: { url, type: 'website' } }));

const html = $input.first().json.data || $input.first().json.body || '';
const url = $('Define URLs').item.json.url;

// Simple HTML to text extraction
let text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .trim();

// Skip if too short
if (text.length < 100) {
  return [];
}

// Chunk the text (roughly 1000 chars per chunk with overlap)
const chunkSize = 1000;
const overlap = 200;
const chunks = [];

for (let i = 0; i < text.length; i += chunkSize - overlap) {
  const chunk = text.slice(i, i + chunkSize).trim();
  if (chunk.length > 50) {
    chunks.push({
      json: {
        content: chunk,
        metadata: {
          source: url,
          type: 'website',
          chunk_index: chunks.length
        }
      }
    });
  }
}

return chunks;
